  const setSermon=(field:string,val:string)=>setPlan({...plan,[field]:val});
  const nid=useRef(Math.max(899,...checkIns.map((c:any)=>+(c.id)||0))+1);const ef=k=>v=>setEvtForm(f=>({...f,[k]:v}));
