  const _rsvpAddDays=(ds:string,n:number)=>{const d=new Date(ds+"T12:00:00");d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);};
  const rsvpUpcoming=(()=>{const out:any[]=[];const start=td();for(let i=0;i<60;i++){const ds=_rsvpAddDays(start,i);cEventsFor(ds,recurring||[],custom||[],[]).forEach((e:any)=>out.push(e));}return out;})();
