  const cancelStaffRsvp=(r:any)=>{setEventRsvps((prev:any)=>{const arr=Array.isArray(prev)?prev:[];return arr.map((x:any)=>x.id===r.id?{...x,status:"canceled",at:new Date().toISOString()}:x);});};
