      if(Array.isArray(d.checkIns)&&d.checkIns.length) setCheckIns(d.checkIns);
      // incidents load from the role-gated church_confidential table, not the blob
      if(Array.isArray(d.rollCalls)&&d.rollCalls.length) setRollCalls(d.rollCalls);
      // progressNotes load from the role-gated church_confidential table, not the blob
      // MERGE teacher schedule by (date+classroom) so the 60s sync poll can't drop a just-saved assignment.
      if(Array.isArray(d.teacherSchedule)) setTeacherSchedule((cur:any[])=>{
        const curArr=Array.isArray(cur)?cur:[];
        const keyOf=(t:any)=>String(t.date)+'|'+String(t.classroomId);
        const have=new Set(curArr.map(keyOf));
        const merged=[...curArr,...d.teacherSchedule.filter((t:any)=>!have.has(keyOf(t)))];
        return merged.length===curArr.length?curArr:merged;
      });
      // MERGE kids check-ins (union by id) instead of replacing — the 60s sync poll must never
