  // ── Always-on "Missed 4 weeks" trigger ── auto-creates Stage-1 teacher follow-ups app-wide
  //    (not only when the Education follow-up tab is open) for any enrolled child whose last
  //    check-in was 4+ weeks ago. Idempotent (one record per child), skips dismissed children.
  useEffect(()=>{
    if(!Array.isArray(children)||!children.length) return;
    if(typeof setTeacherFollowups!=="function") return;
    const dismissed=new Set((followupDismissedChildIds||[]).map((x:any)=>String(x)));
    const stats:any={};
    const addEv=(k:string,d:string)=>{ if(!k||!d) return; if(!stats[k]) stats[k]={first:d,last:d}; else { if(d<stats[k].first)stats[k].first=d; if(d>stats[k].last)stats[k].last=d; } };
    // Count attendance from BOTH the check-in portal and roll-call "Present" marks.
    (kidsCheckIns||[]).forEach((c:any)=>{ addEv(String(c.childId), c.date); });
    (rollCalls||[]).forEach((rc:any)=>{ const d=rc?.date; if(!d) return; (Array.isArray(rc?.entries)?rc.entries:[]).forEach((e:any)=>{ if(String(e?.status||"").toLowerCase()==="present") addEv(String(e.childId), d); }); });
    const missedWeeks=(d:string)=> d?Math.max(0,Math.floor((Date.now()-new Date(d+"T00:00:00").getTime())/(7*24*60*60*1000))):0;
    const mw=Math.max(1,Number(churchSettings?.missedWeeksThreshold)||4);
    const eligible=children.filter((c:any)=>{
      if(dismissed.has(String(c.id))) return false;
      const st=stats[String(c.id)];
      return st&&st.first&&st.last&&missedWeeks(st.last)>=mw;
    });
    // Children who have attended again within the threshold → their stale Stage-1 alert should clear.
    const reAttended=new Set<string>();
    children.forEach((c:any)=>{ const st=stats[String(c.id)]; if(st&&st.last&&missedWeeks(st.last)<mw) reAttended.add(String(c.id)); });
    const stageNorm=(s:any)=>String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"");
    setTeacherFollowups((prev:any)=>{
      const prevArr=Array.isArray(prev)?prev:[];
      // Drop Stage-1 "missed weeks" alerts for kids who have since re-attended within the threshold.
      const pruned=prevArr.filter((r:any)=>!(stageNorm(r?.stage)==="stage1" && reAttended.has(String(r?.childId))));
      const existing=new Set(pruned.map((r:any)=>String(r.childId)));
      const adds=eligible.filter((c:any)=>!existing.has(String(c.id))).map((c:any)=>({
        id:"tf_"+c.id+"_"+Math.floor(Date.now()),
        childId:c.id,childFirst:c.first||"",childLast:c.last||"",
        parentPhone:c.parentPhone||"",parentName:c.parentName||"",
        stage:"stage1",createdAt:new Date().toISOString(),
        firstCheckInDate:stats[String(c.id)]?.first||"",lastCheckInDate:stats[String(c.id)]?.last||"",
        assignedToUserId:null,assignedByUserId:null,assignedAt:null,movedToOngoingAt:null,followUps:[],
      }));
      const result=[...pruned,...adds];
      // Only update state if something actually changed (avoid render churn).
      return (result.length===prevArr.length && adds.length===0) ? prevArr : result;
    });
  },[JSON.stringify((kidsCheckIns||[]).map((c:any)=>c.childId+":"+c.date)),JSON.stringify((rollCalls||[]).map((rc:any)=>rc.date+":"+(Array.isArray(rc.entries)?rc.entries.length:0))),JSON.stringify((children||[]).map((c:any)=>c.id)),JSON.stringify(followupDismissedChildIds||[]),churchSettings?.missedWeeksThreshold]);

  // ── Keep all devices in sync: poll every 60 s + re-sync when tab becomes visible ──
  useEffect(()=>{
    if(!churchId) return;
    const trigger = ()=>{
      if(Date.now()-lastSyncAt.current < 30000) return; // throttle: max once per 30 s
      setSyncTrigger(t=>t+1);
    };
    const interval = setInterval(trigger, 60000);
    const onVisible = ()=>{ if(document.visibilityState==='visible') trigger(); };
    document.addEventListener('visibilitychange', onVisible);
    return()=>{ clearInterval(interval); document.removeEventListener('visibilitychange', onVisible); };
  },[churchId]);

  // ── Debounced Supabase cloud-save (3 s after last change) ──
  useEffect(()=>{
    if(!churchId) return;
    if(sbSyncTimer.current) clearTimeout(sbSyncTimer.current);
    setCloudSync('saving');
    sbSyncTimer.current = setTimeout(async()=>{
      // Cross-tab / cross-device guard: skip save if another tab ran Clear All Data in the last 5 minutes
      const clearedAt = parseInt(localStorage.getItem('ntcc_data_cleared')||'0');
      if(clearedAt && Date.now()-clearedAt < 300000){setCloudSync('idle');return;}
      // Suppress save triggered by a cloud load (not a user change) — wait for the suppress window to expire
      if(suppressSave.current){setCloudSync('idle');return;}
      // Empty-state guard: don't overwrite Supabase with blank data unless THIS device intentionally cleared it.
      // This prevents a phone/tab that loaded empty state from wiping the live database.
      const hasAnyData = members.length>0||visitors.length>0||giving.length>0||attendance.length>0||children.length>0||users.length>0;
      if(!hasAnyData && !(clearedAt && Date.now()-clearedAt < 300000)){setCloudSync('idle');return;}
      // Staleness guard: check if Supabase was updated more recently than our last load.
      // If so, another device saved after us — re-sync instead of overwriting their changes.
      const {data:meta} = await supabase.from('church_data').select('updated_at').eq('church_id',churchId).maybeSingle();
      const remoteTs = meta?.updated_at ? new Date(meta.updated_at).getTime() : 0;
      if(remoteTs > lastSyncAt.current + 2000){
        // Remote is newer than our last load — pull the latest data instead of overwriting
        setSyncTrigger(t=>t+1);
        setCloudSync('idle');
        return;
      }
      // Never persist secrets to the cloud blob: app-user passwords/PINs are unused
      // for auth (login is Supabase), and the email provider key is unused (sending
      // is a stub). Strip them so they aren't synced/exposed in church_data.
      const safeUsers = (users||[]).map(u=>{ const {password,pin,...rest}=u||{}; return rest; });
      const {apiKey:_omitEmailKey, ...safeEmailConfig} = emailConfig||{};
      const blob = {members,visitors,attendance,prayers,groups,grpMeetings,visitRecords,
        children,classrooms,equipment,workOrders,schedMaint,supplies,checkoutItems,checkouts,
        emailLog,emailTemplates,emailConfig:safeEmailConfig,recurring,custom,checkIns,rollCalls,
        teacherSchedule,kidsCheckIns,teacherFollowups,eventRsvps,announcements,roles,permissions,churchSettings,users:safeUsers,prospects,
        followupDismissedChildIds,
        sickVisits,benevolence,hospitalityFund,hospStartBalance,cleaningSchedule,eventSchedule};
      const {error} = await supabase.from('church_data').upsert(
        {church_id:churchId,data:blob,updated_at:new Date().toISOString()},
        {onConflict:'church_id'}
      );
      if(!error) lastSyncAt.current = Date.now();
      setCloudSync(error?'error':'saved');
      // Keep sync errors visible (don't auto-hide) so a failed save isn't silently lost.
      // Only the success state auto-clears; the next data change retries the save.
      if(!error) setTimeout(()=>setCloudSync('idle'),2500);
    },3000);
    // Cheap reference-equality deps (each is a useState value) instead of stringifying the
    // entire database on every render — eliminates per-keystroke serialization lag.
  },[members,visitors,attendance,prayers,groups,grpMeetings,visitRecords,
    children,classrooms,equipment,workOrders,schedMaint,supplies,checkoutItems,checkouts,
    emailLog,emailTemplates,emailConfig,recurring,custom,checkIns,rollCalls,
    teacherSchedule,kidsCheckIns,teacherFollowups,eventRsvps,announcements,roles,permissions,churchSettings,users,prospects,
    followupDismissedChildIds,
    sickVisits,benevolence,hospitalityFund,hospStartBalance,cleaningSchedule,eventSchedule]);

